write('tests/web/landing.spec.ts', `import { test, expect } from '@playwright/test';
import { LandingPage } from './page-objects/landing-page';

// BDD traceability: tests/web/bdd/landing.feature

test.describe('Landing Page', () => {

  test('@smoke @gating — landing page loads with branding', async ({ page }) => {
    const landing = new LandingPage(page);
    await landing.goto();
    await landing.assertLoaded();
    await expect(landing.heading).toBeVisible();
    await expect(landing.loginButton).toBeVisible();
    await expect(landing.signUpButton).toBeVisible();
  });

  test('@smoke @gating — navigate to sign in from landing page', async ({ page }) => {
    const landing = new LandingPage(page);
    await landing.goto();
    await landing.clickLogin();
    await expect(page).toHaveURL(/sign-in/);
  });

  test('@smoke @gating — navigate to sign up from landing page', async ({ page }) => {
    const landing = new LandingPage(page);
    await landing.goto();
    await landing.clickSignUp();
    await expect(page).toHaveURL(/sign-up/);
  });

  test('@regression — navigate to sign up via CTA button', async ({ page }) => {
    const landing = new LandingPage(page);
    await landing.goto();
    await landing.clickSignUpCta();
    await expect(page).toHaveURL(/sign-up/);
  });

});
`);

write('tests/web/auth.spec.ts', `import { test, expect } from '@playwright/test';
import { SignInPage } from './page-objects/sign-in-page';
import { SignUpPage } from './page-objects/sign-up-page';
import { ResetPasswordPage } from './page-objects/reset-password-page';

// BDD traceability: tests/web/bdd/auth.feature

test.describe('Sign Up', () => {

  test('@smoke @gating — sign up with valid details', async ({ page }) => {
    const signUp = new SignUpPage(page);
    await signUp.goto();
    // Unique email per run to avoid conflicts on the demo server
    const uniqueEmail = \`testuser+\${Date.now()}@example.com\`;
    await signUp.fillAndSubmit('Test', 'User', uniqueEmail, 'Secure@123');
    // After successful sign-up, should leave /sign-up
    await expect(page).not.toHaveURL(/sign-up/, { timeout: 10_000 });
  });

  test('@regression — sign up page shows all required fields', async ({ page }) => {
    const signUp = new SignUpPage(page);
    await signUp.goto();
    await signUp.assertLoaded();
  });

});

test.describe('Sign In', () => {

  test('@smoke @gating — sign in form is displayed correctly', async ({ page }) => {
    const signIn = new SignInPage(page);
    await signIn.goto();
    await signIn.assertLoaded();
    await expect(signIn.forgotPasswordLink).toBeVisible();
  });

  test('@regression — sign in page links to sign up', async ({ page }) => {
    const signIn = new SignInPage(page);
    await signIn.goto();
    await expect(signIn.signUpLink).toBeVisible();
  });

  test('@regression — forgot password link navigates to reset page', async ({ page }) => {
    const signIn = new SignInPage(page);
    await signIn.goto();
    await signIn.clickForgotPassword();
    await expect(page).toHaveURL(/reset-password/);
  });

  test('@smoke @gating — unauthenticated access to dashboard redirects to sign in', async ({ page }) => {
    await page.goto('/dashboard');
    await expect(page).toHaveURL(/sign-in/, { timeout: 10_000 });
  });

});

test.describe('Reset Password', () => {

  test('@regression — reset password page shows email field', async ({ page }) => {
    const reset = new ResetPasswordPage(page);
    await reset.goto();
    await reset.assertLoaded();
  });

  test('@regression — back link on reset password navigates to sign in', async ({ page }) => {
    const reset = new ResetPasswordPage(page);
    await reset.goto();
    await reset.clickBack();
    await expect(page).toHaveURL(/sign-in/);
  });

});
`);

